package com.jagan.healthcare.service;
import com.jagan.healthcare.dto.AuthRequest; import com.jagan.healthcare.model.UserAccount; import com.jagan.healthcare.repository.UserAccountRepository; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { private final UserAccountRepository repository; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); public AuthService(UserAccountRepository repository){this.repository=repository;} public UserAccount register(AuthRequest r){if(repository.existsByEmailIgnoreCase(r.getEmail()))throw new IllegalArgumentException("Email is already registered.");return repository.save(new UserAccount(r.getName().trim(),r.getEmail().trim().toLowerCase(),encoder.encode(r.getPassword()),r.getPhone(),"PATIENT"));} public UserAccount login(String email,String password){UserAccount u=repository.findByEmailIgnoreCase(email).orElseThrow(()->new IllegalArgumentException("Invalid email or password."));if(!encoder.matches(password,u.getPassword()))throw new IllegalArgumentException("Invalid email or password.");return u;} }
